<script module lang="ts">
/**
 * AppShell.NavItem: a row of the rail, start-aligned, a link or a button.
 *
 * Generated by `pnpm shells` from `packages/shells/src/members/app-shell.ts`, the member's
 * framework-neutral description. Never edit it by hand: change the description and
 * run `pnpm shells`.
 */
import { getContext, type Snippet } from 'svelte'

import { Icon, joinSlot, type IconRole } from '@polymorph/svelte'
import styles from '@polymorph/recipes/archetypes/app-shell.module.css'
import Tooltip from '../overlays/Tooltip.svelte'

export interface AppShellNavItemProps {
  /**
   * Expected in practice, because a collapsed rail is unusable without icons.
   */
  icon?: IconRole
  /**
   * The accessible name in every mode, including collapsed.
   */
  label: string
  /**
   * Marks the current page, with exactly one per rail.
   */
  current?: boolean
  /**
   * With an `href`, the row is an `<a>` with Link's semantics and NavItem's styling.
   */
  href?: string
  /**
   * The app's router, on a row with an `href`: a click that would navigate this tab calls it in
   * place of the browser.
   */
  onNavigate?: (href: string) => void
  /**
   * For a rail of buttons that routes in script with no `href`; it also fires on every click of
   * a row with one.
   */
  onSelect?: () => void
  /**
   * Trailing content, by convention a Badge with a count.
   */
  end?: Snippet
}
</script>

<script lang="ts">
let {
  icon,
  label: labelOwn,
  current = false,
  href,
  onNavigate,
  onSelect,
  end,
}: AppShellNavItemProps = $props()
const joined = joinSlot(undefined, () => ({ label: labelOwn }))
const label = $derived(
  joined.passed['label'] === undefined ? labelOwn : (joined.passed['label'] as typeof labelOwn),
)
const owner: Record<string, any> = getContext('polymorph:AppShell') ?? {}
const listening = {
  get navigate() {
    return onNavigate !== undefined
  },
  get select() {
    return onSelect !== undefined
  },
}
const slots = {
  get end() {
    return end
  },
}
const navigatesHere = $derived(
  (event: MouseEvent): boolean =>
    !event.defaultPrevented &&
    event.button === 0 &&
    !event.metaKey &&
    !event.ctrlKey &&
    !event.shiftKey &&
    !event.altKey,
)
const route = $derived((event: MouseEvent): void => {
  if (href === undefined || !listening.navigate || !navigatesHere(event)) return
  event.preventDefault()
  onNavigate?.(href)
})
</script>

{@render joined.start?.()
}{#if joined.shown
  }{#if owner.collapsed === true
    }<Tooltip content={label} side="right"
      >{#if href === undefined
        }<button
          class={styles.navItem}
          type="button"
          aria-current={(current) ? 'page' : undefined}
          data-current={(current) ? '' : undefined}
          onclick={() => { onSelect?.() }}
          >{#if icon !== undefined}<span class={styles.navGlyph}><Icon name={icon} /></span>{/if
          }<span class={styles.navLabel}>{label}</span
          >{#if slots.end}<span class={styles.navEnd}>{@render end?.()}</span>{/if
        }</button
      >{:else
        }<a
          class={styles.navItem}
          {href}
          aria-current={(current) ? 'page' : undefined}
          data-current={(current) ? '' : undefined}
          onclick={(event) => { (onSelect?.(), route(event)) }}
          >{#if icon !== undefined}<span class={styles.navGlyph}><Icon name={icon} /></span>{/if
          }<span class={styles.navLabel}>{label}</span
          >{#if slots.end}<span class={styles.navEnd}>{@render end?.()}</span>{/if
        }</a
      >{/if
    }</Tooltip
  >{:else
    }{#if href === undefined
      }<button
        class={styles.navItem}
        type="button"
        aria-current={(current) ? 'page' : undefined}
        data-current={(current) ? '' : undefined}
        onclick={() => { onSelect?.() }}
        >{#if icon !== undefined}<span class={styles.navGlyph}><Icon name={icon} /></span>{/if
        }<span class={styles.navLabel}>{label}</span
        >{#if slots.end}<span class={styles.navEnd}>{@render end?.()}</span>{/if
      }</button
    >{:else
      }<a
        class={styles.navItem}
        {href}
        aria-current={(current) ? 'page' : undefined}
        data-current={(current) ? '' : undefined}
        onclick={(event) => { (onSelect?.(), route(event)) }}
        >{#if icon !== undefined}<span class={styles.navGlyph}><Icon name={icon} /></span>{/if
        }<span class={styles.navLabel}>{label}</span
        >{#if slots.end}<span class={styles.navEnd}>{@render end?.()}</span>{/if
      }</a
    >{/if
  }{/if
}{/if
}{@render joined.end?.()}
